<?php
namespace App\Services\Notification;use App\Models\User;use Illuminate\Support\Facades\DB;
class NotificationService{public function send(int|User $user,string $type,string $title,string $message,?string $url=null,array $data=[]):int{return DB::table('user_notifications')->insertGetId(['user_id'=>$user instanceof User?$user->id:$user,'type'=>$type,'title'=>$title,'message'=>$message,'action_url'=>$url,'data'=>$data?json_encode($data,JSON_UNESCAPED_UNICODE):null,'created_at'=>now(),'updated_at'=>now()]);}public function broadcast(string $title,string $message,?string $url=null):int{$now=now();$rows=User::query()->pluck('id')->map(fn($id)=>['user_id'=>$id,'type'=>'announcement','title'=>$title,'message'=>$message,'action_url'=>$url,'created_at'=>$now,'updated_at'=>$now])->all();foreach(array_chunk($rows,500)as $chunk)DB::table('user_notifications')->insert($chunk);return count($rows);}}
